import { describe, expect, it, beforeEach, afterEach } from "vitest";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import {
  API_KEY_FILENAME,
  apiKeyFilePath,
  loadOrCreatePersistedApiKey,
  publishSharedApiKey,
  readPersistedApiKey,
  shodhDataRoot,
} from "../api-key-store";

let tmpRoot: string;

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "shodh-key-test-"));
});

afterEach(() => {
  fs.rmSync(tmpRoot, { recursive: true, force: true });
});

describe("shodhDataRoot", () => {
  it("prefers SHODH_MEMORY_PATH when set", () => {
    const root = shodhDataRoot({ SHODH_MEMORY_PATH: "/custom/data" } as NodeJS.ProcessEnv, "linux", "/home/u");
    expect(root).toBe("/custom/data");
  });

  it("uses %APPDATA%/shodh-memory on Windows (matches Rust dirs::data_dir)", () => {
    const root = shodhDataRoot(
      { APPDATA: "C:\\Users\\John Smith\\AppData\\Roaming" } as NodeJS.ProcessEnv,
      "win32",
      "C:\\Users\\John Smith",
    );
    expect(root).toBe(path.join("C:\\Users\\John Smith\\AppData\\Roaming", "shodh-memory"));
  });

  it("falls back to <home>/AppData/Roaming when APPDATA is unset on Windows", () => {
    const root = shodhDataRoot({} as NodeJS.ProcessEnv, "win32", "C:\\Users\\John Smith");
    expect(root).toBe(path.join("C:\\Users\\John Smith", "AppData", "Roaming", "shodh-memory"));
  });

  it("uses Application Support on macOS", () => {
    const root = shodhDataRoot({} as NodeJS.ProcessEnv, "darwin", "/Users/u");
    expect(root).toBe(path.join("/Users/u", "Library", "Application Support", "shodh-memory"));
  });

  it("respects XDG_DATA_HOME on Linux, defaulting to ~/.local/share", () => {
    expect(shodhDataRoot({ XDG_DATA_HOME: "/xdg" } as NodeJS.ProcessEnv, "linux", "/home/u")).toBe(
      path.join("/xdg", "shodh-memory"),
    );
    expect(shodhDataRoot({} as NodeJS.ProcessEnv, "linux", "/home/u")).toBe(
      path.join("/home/u", ".local", "share", "shodh-memory"),
    );
  });
});

describe("loadOrCreatePersistedApiKey", () => {
  it("generates and persists a key when none exists", () => {
    const result = loadOrCreatePersistedApiKey(tmpRoot, () => "generated-key-1");
    expect(result.created).toBe(true);
    expect(result.key).toBe("generated-key-1");
    expect(result.file).toBe(path.join(tmpRoot, API_KEY_FILENAME));
    expect(fs.readFileSync(result.file, "utf-8").trim()).toBe("generated-key-1");
  });

  it("returns the SAME key on subsequent calls instead of regenerating (the T15 race fix)", () => {
    const first = loadOrCreatePersistedApiKey(tmpRoot, () => "first-shim-key");
    // A second shim with a different generator must get the first shim's key.
    const second = loadOrCreatePersistedApiKey(tmpRoot, () => "second-shim-key");
    expect(first.key).toBe("first-shim-key");
    expect(second.key).toBe("first-shim-key");
    expect(second.created).toBe(false);
  });

  it("never invokes the generator when a key is already persisted", () => {
    fs.mkdirSync(tmpRoot, { recursive: true });
    fs.writeFileSync(path.join(tmpRoot, API_KEY_FILENAME), "existing-key\n");
    const result = loadOrCreatePersistedApiKey(tmpRoot, () => {
      throw new Error("generator must not be called when a key exists");
    });
    expect(result.key).toBe("existing-key");
    expect(result.created).toBe(false);
  });

  it("creates the data root directory when missing", () => {
    const nested = path.join(tmpRoot, "deep", "nested", "root");
    const result = loadOrCreatePersistedApiKey(nested, () => "k");
    expect(result.created).toBe(true);
    expect(readPersistedApiKey(apiKeyFilePath(nested))).toBe("k");
  });

  it("heals an empty key file left by a crashed writer", () => {
    fs.mkdirSync(tmpRoot, { recursive: true });
    fs.writeFileSync(path.join(tmpRoot, API_KEY_FILENAME), "");
    const result = loadOrCreatePersistedApiKey(tmpRoot, () => "healed-key");
    expect(result.key).toBe("healed-key");
    expect(readPersistedApiKey(apiKeyFilePath(tmpRoot))).toBe("healed-key");
  });

  it("restricts key file permissions on POSIX", () => {
    if (process.platform === "win32") return; // mode bits are not meaningful on Windows
    const result = loadOrCreatePersistedApiKey(tmpRoot, () => "k");
    const mode = fs.statSync(result.file).mode & 0o777;
    expect(mode).toBe(0o600);
  });
});

describe("readPersistedApiKey", () => {
  it("returns null for missing or empty files, trimmed content otherwise", () => {
    const file = path.join(tmpRoot, API_KEY_FILENAME);
    expect(readPersistedApiKey(file)).toBeNull();
    fs.writeFileSync(file, "   \n");
    expect(readPersistedApiKey(file)).toBeNull();
    fs.writeFileSync(file, "  the-key \n");
    expect(readPersistedApiKey(file)).toBe("the-key");
  });
});

describe("publishSharedApiKey — sharing an environment-supplied key with hooks", () => {
  it("writes the key so a hook reading the same root finds it", () => {
    // The gap this closes: an MCP client's `env` block reaches the shim but not
    // Claude Code's hooks, which then fall back to the dev key and get 401s.
    expect(publishSharedApiKey(tmpRoot, "sk-from-mcp-json")).toBe(true);
    expect(readPersistedApiKey(apiKeyFilePath(tmpRoot))).toBe("sk-from-mcp-json");
  });

  it("creates the root directory when it does not exist yet", () => {
    const nested = path.join(tmpRoot, "does", "not", "exist");
    expect(publishSharedApiKey(nested, "sk-nested")).toBe(true);
    expect(readPersistedApiKey(apiKeyFilePath(nested))).toBe("sk-nested");
  });

  it("reports no write when the file already holds this key", () => {
    publishSharedApiKey(tmpRoot, "sk-same");
    expect(publishSharedApiKey(tmpRoot, "sk-same")).toBe(false);
  });

  it("overwrites a stale key so a changed config self-heals", () => {
    // Unlike first-time generation, a configured key is authoritative: if the
    // user edits SHODH_API_KEY, the file must follow or hooks keep 401ing.
    publishSharedApiKey(tmpRoot, "sk-old");
    expect(publishSharedApiKey(tmpRoot, "sk-new")).toBe(true);
    expect(readPersistedApiKey(apiKeyFilePath(tmpRoot))).toBe("sk-new");
  });

  it("leaves a published key readable by loadOrCreatePersistedApiKey", () => {
    // A sibling shim with no key configured must adopt the published key
    // rather than generating a second one.
    publishSharedApiKey(tmpRoot, "sk-published");
    const loaded = loadOrCreatePersistedApiKey(tmpRoot, () => "sk-should-not-be-used");
    expect(loaded.key).toBe("sk-published");
    expect(loaded.created).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import {
  buildProgressBar,
  extractStringContextFromArgs,
  formatResetTokenSessionText,
  formatTokenStatusText,
  normalizeLimit,
  shouldAppendProactiveContext,
  describeUserId,
} from "../index-helpers";

describe("buildProgressBar", () => {
  it("builds 20-char bar", () => {
    const bar = buildProgressBar(50);
    expect(bar.length).toBe(20);
    expect(bar).toContain("█");
    expect(bar).toContain("░");
  });

  it("clamps percent bounds", () => {
    expect(buildProgressBar(-10)).toBe("░".repeat(20));
    expect(buildProgressBar(150)).toBe("█".repeat(20));
  });
});

describe("formatTokenStatusText", () => {
  it("formats healthy status", () => {
    const text = formatTokenStatusText(
      { tokens: <REDACTED> budget: 1000, percent: 0.1, alert: null },
      5,
    );
    expect(text).toContain("Token Status");
    expect(text).toContain("Used: 100 tokens");
    expect(text).toContain("Budget: 1,000 tokens");
    expect(text).toContain("Remaining: 900 tokens");
    expect(text).toContain("Context window healthy");
  });

  it("formats alert status", () => {
    const text = formatTokenStatusText(
      { tokens: <REDACTED> budget: 1000, percent: 0.95, alert: "context_90_percent" },
      12,
    );
    expect(text).toContain("ALERT");
    expect(text).toContain("95% used");
  });
});

describe("normalizeLimit", () => {
  it("defaults when undefined", () => {
    expect(normalizeLimit(undefined)).toBe(10);
  });

  it("enforces minimum", () => {
    expect(normalizeLimit(0)).toBe(1);
    expect(normalizeLimit(-5)).toBe(1);
  });

  it("enforces maximum", () => {
    expect(normalizeLimit(999, 250)).toBe(250);
  });

  it("floors decimals", () => {
    expect(normalizeLimit(7.9)).toBe(7);
  });
});

describe("formatResetTokenSessionText", () => {
  it("formats reset text with prior usage and budget", () => {
    const text = formatResetTokenSessionText(12500, 100000);
    expect(text).toContain("Token Session Reset");
    expect(text).toContain("Previous: 12,500 tokens");
    expect(text).toContain("Current: 0 tokens");
    expect(text).toContain("Budget: 100,000 tokens");
    expect(text).toContain("Counter cleared");
  });
});

describe("shouldAppendProactiveContext", () => {
  it("returns false for excluded memory-management tools", () => {
    expect(shouldAppendProactiveContext("remember")).toBe(false);
    expect(shouldAppendProactiveContext("recall")).toBe(false);
    expect(shouldAppendProactiveContext("memory_stats")).toBe(false);
  });

  it("returns true for normal tools", () => {
    expect(shouldAppendProactiveContext("search_code")).toBe(true);
    expect(shouldAppendProactiveContext("read_file")).toBe(true);
  });
});

describe("extractStringContextFromArgs", () => {
  it("extracts only sufficiently long string values", () => {
    const context = extractStringContextFromArgs({
      short: "abc",
      good: "this should be included",
      count: 42,
      nested: { x: 1 },
      alsoGood: "another long value",
    });
    expect(context).toContain("this should be included");
    expect(context).toContain("another long value");
    expect(context).not.toContain("abc");
  });

  it("caps output length", () => {
    const veryLong = "x".repeat(3000);
    const context = extractStringContextFromArgs({ a: veryLong }, 1, 1000);
    expect(context.length).toBe(1000);
  });

  it("returns empty string for non-object args", () => {
    expect(extractStringContextFromArgs(null)).toBe("");
    expect(extractStringContextFromArgs("text")).toBe("");
  });
});

describe("describeUserId", () => {
  const EMAIL = "alice@example.com";

  it("passes the default through unchanged — it is not sensitive", () => {
    expect(describeUserId("claude-code")).toBe("claude-code");
  });

  // The regression this pins: the banner is written to stderr, which clients
  // persist. An operator who puts an email in SHODH_USER_ID must not find it
  // there, and no substring of it either — a prefix leaks the local-part.
  it("never emits the raw id or any substring of it", () => {
    const out = describeUserId(EMAIL);
    expect(out).not.toContain(EMAIL);
    expect(out).not.toContain("alice");
    expect(out).not.toContain("example.com");
    expect(out).not.toContain("@");
  });

  // Only the hash may be derived from userId. .length is not a sanitiser and
  // reintroduced a js/clear-text-logging finding when it was included.
  it("emits the digest and nothing else derived from the id", () => {
    expect(describeUserId(EMAIL)).toBe("custom (sha256:ff8d9819)");
    expect(describeUserId(EMAIL)).not.toMatch(/len|length|\d+ chars/);
  });

  it("is reproducible, so an operator can confirm which id is live", () => {
    expect(describeUserId(EMAIL)).toBe(describeUserId(EMAIL));
    expect(describeUserId("prod-team")).not.toBe(describeUserId(EMAIL));
  });

  // Trailing whitespace from a shell export is the common misconfiguration.
  // The digest alone distinguishes it, which is why the length was redundant.
  it("distinguishes a trailing newline without reporting the length", () => {
    expect(describeUserId(EMAIL + "\n")).not.toBe(describeUserId(EMAIL));
  });

  it("handles the empty string without emitting it", () => {
    const out = describeUserId("");
    expect(out).toMatch(/^custom \(sha256:[0-9a-f]{8}\)$/);
  });
});

import { createHmac, randomUUID } from "node:crypto";
import { existsSync, rmSync } from "node:fs";
import { createServer, type Server, type Socket } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  IPC_MAX_FRAME_BYTES,
  IPC_PROTOCOL_VERSION,
  IpcApiError,
  ShodhIpcClient,
  type WindowsIpcHelper,
} from "../ipc-client";

const NONCE = Buffer.alloc(32, 0x5a);
const PROBE_RESPONSE_DOMAIN = Buffer.from("shodh-ipc-v2/server-proof", "utf8");
const REQUEST_DOMAIN = Buffer.from("shodh-ipc-v2/request", "utf8");
const RESPONSE_DOMAIN = Buffer.from("shodh-ipc-v2/response", "utf8");
const WINDOWS_TEST_HELPER = String.raw`
const fs = require("node:fs");
const endpointIndex = process.argv.indexOf("--ipc-endpoint");
const endpoint = process.argv[endpointIndex + 1];
const request = fs.readFileSync(0);
let descriptor;
try {
  for (;;) {
    try {
      descriptor = fs.openSync(endpoint, fs.constants.O_RDWR);
      break;
    } catch (error) {
      if (error.code !== "EBUSY" && error.code !== "EAGAIN") throw error;
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
    }
  }
  fs.writeSync(descriptor, request);
  const chunks = [];
  for (;;) {
    const chunk = Buffer.allocUnsafe(8192);
    let count;
    try { count = fs.readSync(descriptor, chunk, 0, chunk.length, null); }
    catch (error) { if (error.code === "EPIPE") break; throw error; }
    if (count === 0) break;
    chunks.push(chunk.subarray(0, count));
  }
  fs.writeFileSync(1, Buffer.concat(chunks));
} catch (error) {
  fs.writeFileSync(2, String(error && error.message ? error.message : error));
  process.exitCode = 1;
} finally {
  if (descriptor !== undefined) try { fs.closeSync(descriptor); } catch {}
}`;

const servers: Server[] = [];
const unixEndpoints: string[] = [];

afterEach(async () => {
  await Promise.all(servers.splice(0).map((server) => closeServer(server)));
  for (const endpoint of unixEndpoints.splice(0)) {
    if (existsSync(endpoint)) rmSync(endpoint, { force: true });
  }
});

describe("ShodhIpcClient", () => {
  it("authenticates the endpoint without transmitting the API key", async () => {
    let captured: RequestRecord | undefined;
    const endpoint = await listen((socket, request) => {
      captured = request;
      socket.end(encodeResponse(signedResponse(request, "secret-key", 200, { memories: [] })));
    }, "secret-key");

    const client = makeClient(endpoint, "secret-key");
    await expect(client.request("/api/recall", "POST", { query: "hello" }, 1_000))
      .resolves.toEqual({ memories: [] });
    expect(captured).toMatchObject({
      v: IPC_PROTOCOL_VERSION,
      challenge: "",
      method: "POST",
      path: "/api/recall",
      body: { query: "hello" },
    });
    expect(captured?.auth).toMatch(/^request:[0-9a-f]{64}:[0-9a-f]{64}$/);
    expect(requestProofIsValid(captured!, "secret-key")).toBe(true);
    expect(JSON.stringify(captured)).not.toContain("secret-key");
    expect(captured?.id).toMatch(/^[0-9a-f-]{36}$/);
  });

  it("maps signed non-success statuses to API-compatible errors", async () => {
    const endpoint = await listen((socket, request) => {
      socket.end(encodeResponse(signedResponse(
        request,
        "wrong-key",
        401,
        { code: "INVALID_API_KEY", message: "Invalid API key" },
      )));
    }, "wrong-key");

    const client = makeClient(endpoint, "wrong-key");
    const error = await client.request("/api/users", "GET", null, 1_000).catch((cause) => cause);
    expect(error).toBeInstanceOf(IpcApiError);
    expect(error).toMatchObject({ status: 401 });
    expect((error as Error).message).toContain("INVALID_API_KEY");
  });

  it("rejects a health response without a valid server proof", async () => {
    const endpoint = await listen((socket, request) => {
      socket.end(encodeResponse({
        v: IPC_PROTOCOL_VERSION,
        id: request.id,
        auth: "",
        status: 200,
        body: { ok: true },
      }));
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("did not authenticate the server");
  });

  it("rejects a response with the wrong protocol version", async () => {
    const endpoint = await listen((socket, request) => {
      socket.end(encodeResponse({
        v: IPC_PROTOCOL_VERSION + 1,
        id: request.id,
        auth: "",
        status: 200,
        body: {},
      }));
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("Unsupported Shodh IPC response version");
  });

  it("rejects a response whose request ID does not match", async () => {
    const endpoint = await listen((socket) => {
      socket.end(encodeResponse({
        v: IPC_PROTOCOL_VERSION,
        id: randomUUID(),
        auth: "",
        status: 200,
        body: {},
      }));
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("request ID did not match");
  });

  it("rejects fields outside the strict version two response envelope", async () => {
    const endpoint = await listen((socket, request) => {
      socket.end(JSON.stringify({
        v: IPC_PROTOCOL_VERSION,
        id: request.id,
        auth: "",
        status: 200,
        body: {},
        extra: true,
      }) + "\n");
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("fields did not match");
  });

  it("waits for close and rejects a second response frame", async () => {
    const endpoint = await listen((socket, request) => {
      socket.write(encodeResponse(signedProbeResponse(request, "key")));
      setTimeout(() => socket.end("{}\n"), 10);
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("data after");
  });

  it("rejects invalid UTF-8 responses", async () => {
    const endpoint = await listen((socket) => {
      socket.end(Buffer.from([0xc3, 0x28, 0x0a]));
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 1_000))
      .rejects.toThrow("not valid UTF-8");
  });

  it("rejects response frames over eight MiB", async () => {
    const endpoint = await listen((socket) => {
      socket.end(Buffer.alloc(IPC_MAX_FRAME_BYTES + 1, 0x20));
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 2_000))
      .rejects.toThrow("response exceeds");
  });

  it("enforces one total connect and probe deadline", async () => {
    const endpoint = await listen(() => {
      // Keep the accepted connection open without replying.
    }, "key", false);

    await expect(makeClient(endpoint, "key").request("/health", "GET", null, 30))
      .rejects.toThrow("timed out");
  });

  it("rejects oversized requests before opening a connection", async () => {
    const client = makeClient(testEndpoint(), "key");
    const oversized = "x".repeat(IPC_MAX_FRAME_BYTES);
    await expect(client.request("/api/remember", "POST", { content: oversized }, 1_000))
      .rejects.toThrow("request exceeds");
  });
});

interface RequestRecord {
  v: number;
  id: string;
  auth: string;
  challenge: string;
  method: string;
  path: string;
  body: unknown;
}

interface ResponseRecord {
  v: number;
  id: string;
  auth: string;
  status: number;
  body: unknown;
}

async function listen(
  onRequest: (socket: Socket, request: RequestRecord) => void,
  apiKey: <REDACTED>
  autoProbe = true,
): Promise<string> {
  const endpoint = testEndpoint();
  const server = createServer((socket) => {
    let frame = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      frame = Buffer.concat([frame, chunk]);
      const newline = frame.indexOf(0x0a);
      if (newline === -1) return;
      const request = JSON.parse(frame.subarray(0, newline).toString("utf8")) as RequestRecord;
      if (autoProbe && request.method === "GET" && request.path === "/health") {
        socket.end(encodeResponse(signedProbeResponse(request, apiKey)));
      } else {
        onRequest(socket, request);
      }
    });
  });
  servers.push(server);
  if (process.platform !== "win32") unixEndpoints.push(endpoint);
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(endpoint, resolve);
  });
  return endpoint;
}

function signedProbeResponse(request: RequestRecord, key: string): ResponseRecord {
  const status = 200;
  const proof = macHex(key, PROBE_RESPONSE_DOMAIN, [
    Buffer.from(request.id, "utf8"),
    Buffer.from(request.challenge, "utf8"),
    NONCE,
    u16(status),
  ]);
  return {
    v: IPC_PROTOCOL_VERSION,
    id: request.id,
    auth: `probe:${NONCE.toString("hex")}:${proof}`,
    status,
    body: { ok: true },
  };
}

function signedResponse(
  request: RequestRecord,
  key: string,
  status: number,
  body: unknown,
): ResponseRecord {
  const proof = macHex(key, RESPONSE_DOMAIN, [
    NONCE,
    Buffer.from(request.auth, "utf8"),
    Buffer.from(request.id, "utf8"),
    u16(status),
  ]);
  return {
    v: IPC_PROTOCOL_VERSION,
    id: request.id,
    auth: `response:${proof}`,
    status,
    body,
  };
}

function requestProofIsValid(request: RequestRecord, key: string): boolean {
  const [kind, nonceHex, proof, ...trailing] = request.auth.split(":");
  if (kind !== "request" || !nonceHex || !proof || trailing.length > 0) return false;
  const version = u16(request.v);
  const expected = macHex(key, REQUEST_DOMAIN, [
    Buffer.from(nonceHex, "hex"),
    version,
    Buffer.from(request.id, "utf8"),
    Buffer.from(request.method, "utf8"),
    Buffer.from(request.path, "utf8"),
    Buffer.from(JSON.stringify(request.body), "utf8"),
  ]);
  return nonceHex === NONCE.toString("hex") && proof === expected;
}

function macHex(key: string, domain: Buffer, fields: Buffer[]): string {
  const mac = createHmac("sha256", key);
  for (const field of [domain, ...fields]) {
    const length = Buffer.alloc(8);
    length.writeBigUInt64BE(BigInt(field.byteLength));
    mac.update(length);
    mac.update(field);
  }
  return mac.digest("hex");
}

function u16(value: number): Buffer {
  const encoded = Buffer.alloc(2);
  encoded.writeUInt16BE(value);
  return encoded;
}

function encodeResponse(response: ResponseRecord): string {
  return `${JSON.stringify(response)}\n`;
}

function makeClient(endpoint: string, key: string): ShodhIpcClient {
  return new ShodhIpcClient(endpoint, key, windowsTestHelper());
}

function windowsTestHelper(): WindowsIpcHelper | undefined {
  return process.platform === "win32"
    ? { command: process.execPath, args: ["-e", WINDOWS_TEST_HELPER, "--"] }
    : undefined;
}

function testEndpoint(): string {
  const suffix = `${process.pid}-${randomUUID()}`;
  return process.platform === "win32"
    ? `\\\\.\\pipe\\shodh-ipc-test-${suffix}`
    : join(tmpdir(), `shodh-ipc-test-${suffix}.sock`);
}

function closeServer(server: Server): Promise<void> {
  return new Promise((resolve) => {
    server.close(() => resolve());
  });
}

import { describe, expect, it } from "vitest";
import {
  isLocalHostFromUrl,
  shouldWarnInsecureApiUrl,
  serializeAndValidateBody,
  nextReconnectDelay,
} from "../security-utils";

// =============================================================================
// isLocalHostFromUrl
// =============================================================================
describe("isLocalHostFromUrl", () => {
  it("returns true for localhost", () => {
    expect(isLocalHostFromUrl("http://localhost:3030")).toBe(true);
  });

  it("returns true for 127.0.0.1", () => {
    expect(isLocalHostFromUrl("http://127.0.0.1:3030")).toBe(true);
  });

  it("returns false for ::1 with brackets (URL parser includes brackets)", () => {
