/**
 * Persisted API key shared between every local shodh-memory client.
 *
 * Problem this solves: when no key is configured in the environment, each MCP
 * shim used to generate its own random key in memory. Two shims starting
 * concurrently would each generate a different key — whichever one lost the
 * spawn race then received 401s for the rest of the session. Claude Code hooks
 * (memory-hook.ts and the .sh hooks) had no way to learn the auto-generated
 * key at all, so capture died silently on every fresh install.
 *
 * Mechanism: the first shim to need a key generates one and persists it to
 * `<data-root>/.api-key`, created atomically so exactly one writer wins.
 * Every other shim — and every hook — reads that file. The data root matches
 * the Rust server's default storage path (`dirs::data_dir()/shodh-memory`,
 * see src/config.rs::default_storage_path), or SHODH_MEMORY_PATH when set.
 * The key file sits beside the server's subdirectories (`storage/`,
 * `bm25_index/`) — never inside a RocksDB directory.
 *
 * NOTE: hooks/memory-hook.ts ships as a single self-contained file and cannot
 * import this module. It duplicates the read-side path resolution — keep the
 * two in sync (search for API_KEY_FILENAME there).
 */

import * as fs from "fs";
import * as os from "os";
import * as path from "path";

export const API_KEY_FILENAME = "<REDACTED>";

/**
 * Resolve the directory that holds the shared key and pidfiles:
 *   - SHODH_MEMORY_PATH when set
 *   - Windows: %APPDATA%\shodh-memory
 *   - macOS:   ~/Library/Application Support/shodh-memory
 *   - Linux:   $XDG_DATA_HOME/shodh-memory or ~/.local/share/shodh-memory
 *
 * This is NOT a faithful mirror of the Rust server's `default_storage_path()`
 * (src/config.rs): that function first returns `./shodh_memory_data` when such
 * a directory exists in the server's working directory, and this one has no
 * equivalent branch. Harmless today — the server receives its key through the
 * environment and never reads this file, and every reader (shim and hooks)
 * resolves the root the same way, so they always agree with each other. It
 * matters only if something later assumes the key file sits next to the
 * database. Do not "fix" this by claiming parity in a comment; if real parity
 * is ever needed, port the legacy branch and say so here.
 */
export function shodhDataRoot(
  env: NodeJS.ProcessEnv = process.env,
  platform: NodeJS.Platform = process.platform,
  homeDir: string = os.homedir(),
): string {
  const explicit = env.SHODH_MEMORY_PATH?.trim();
  if (explicit) return explicit;

  if (platform === "win32") {
    const appData = env.APPDATA?.trim() || path.join(homeDir, "AppData", "Roaming");
    return path.join(appData, "shodh-memory");
  }
  if (platform === "darwin") {
    return path.join(homeDir, "Library", "Application Support", "shodh-memory");
  }
  const xdg = env.XDG_DATA_HOME?.trim() || path.join(homeDir, ".local", "share");
  return path.join(xdg, "shodh-memory");
}

export function apiKeyFilePath(rootDir: string): string {
  return path.join(rootDir, API_KEY_FILENAME);
}

/** Read a persisted key. Returns null when the file is missing or empty. */
export function readPersistedApiKey(file: string): string | null {
  try {
    const raw = fs.readFileSync(file, "utf-8").trim();
    return raw.length > 0 ? raw : null;
  } catch {
    return null;
  }
}

/** Synchronous sleep without spinning the CPU (used only in a rare race window). */
function sleepSync(ms: number): void {
  const sab = new SharedArrayBuffer(4);
  Atomics.wait(new Int32Array(sab), 0, 0, ms);
}

/**
 * Create `file` with `content` if and only if it does not already exist.
 * Returns true when this process created the file, false when it already
 * existed (i.e. another process won the race).
 *
 * Primary strategy: write a private temp file, then hard-link it into place.
 * link(2) fails with EEXIST if the target exists and — unlike open(O_EXCL) +
 * write — makes the complete content appear atomically, so a concurrent
 * reader can never observe a partially written key. Falls back to an
 * exclusive write on filesystems without hard-link support.
 */
function createExclusive(file: string, content: string): boolean {
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tmp, content, { mode: 0o600 });
  try {
    fs.linkSync(tmp, file);
    return true;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "EEXIST") return false;
    // Hard links unsupported here — fall back to exclusive create.
    try {
      fs.writeFileSync(file, content, { flag: "wx", mode: 0o600 });
      return true;
    } catch (wxErr) {
      if ((wxErr as NodeJS.ErrnoException).code === "EEXIST") return false;
      throw wxErr;
    }
  } finally {
    try {
      fs.unlinkSync(tmp);
    } catch {
      // Best effort: tmp already gone or was renamed away.
    }
  }
}

/** Atomically replace `file` with `content` (used to heal an empty/corrupt key file). */
function replaceAtomic(file: string, content: string): void {
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tmp, content, { mode: 0o600 });
  fs.renameSync(tmp, file);
}

/**
 * Publish an already-resolved key (one that came from the environment) to the
 * shared file so hooks can find it.
 *
 * Why this exists: an MCP client's `env` block — the normal way to configure
 * SHODH_API_KEY — is visible only to the shim process. Claude Code hooks are
 * spawned by Claude Code itself and never see it, so without this they fall
 * back to the legacy dev key and get 401s. Auto-generated keys were already
 * shared via loadOrCreatePersistedApiKey; this closes the same gap for the
 * more common configured-key case.
 *
 * Callers MUST gate this on the backend being local — a remote/production key
 * does not belong on disk just because a hook might want it.
 *
 * Returns true when the file was created or updated, false when it already
 * held this key (the steady state, so the common path does no writes).
 */
export function publishSharedApiKey(rootDir: string, key: string): boolean {
  const file = apiKeyFilePath(rootDir);
  if (readPersistedApiKey(file) === key) return false;
  fs.mkdirSync(rootDir, { recursive: true });
  // Replace rather than create-exclusive: the configured key is authoritative,
  // and rewriting it is how a stale key from an earlier config self-heals.
  replaceAtomic(file, key + "\n");
  return true;
}

export interface PersistedApiKey {
  key: string;
  file: string;
  /** True when this call generated and persisted a new key. */
  created: boolean;
}

/**
 * Load the shared API key, generating and persisting one if none exists yet.
 *
 * Concurrency contract: any number of processes may call this at the same
 * time; exactly one generates the key, and every caller returns the same
 * value. Losers of the creation race read the winner's file (with a short
 * bounded retry to cover the wx-fallback write window).
 */
export function loadOrCreatePersistedApiKey(
  rootDir: string,
  generate: () => string,
): PersistedApiKey {
  const file = apiKeyFilePath(rootDir);

  const existing = readPersistedApiKey(file);
  if (existing) return { key: existing, file, created: false };

  fs.mkdirSync(rootDir, { recursive: true });

  const candidate = generate();
  if (createExclusive(file, candidate + "\n")) {
    return { key: candidate, file, created: true };
  }

  // Another process created the file first — read the winner's key.
  for (let attempt = 0; attempt < 20; attempt++) {
    const winner = readPersistedApiKey(file);
    if (winner) return { key: winner, file, created: false };
    sleepSync(25);
  }

  // The file exists but never became readable/non-empty: a writer crashed
  // mid-create. Heal it by atomically installing our candidate.
  replaceAtomic(file, candidate + "\n");
  return { key: candidate, file, created: true };
}

import * as crypto from "crypto";

export interface TokenStatusShape {
  tokens: <REDACTED>
  budget: number;
  percent: number;
  alert: string | null;
}

const PROACTIVE_EXCLUDED_TOOLS = new Set([
  "remember",
  "recall",
  "forget",
  "list_memories",
  "proactive_context",
  "context_summary",
  "memory_stats",
]);

export function buildProgressBar(percentUsed: number, barLength = 20): string {
  const clamped = Math.max(0, Math.min(100, Math.round(percentUsed)));
  const filledLength = Math.round((clamped / 100) * barLength);
  return "█".repeat(filledLength) + "░".repeat(barLength - filledLength);
}

export function formatTokenStatusText(
  status: TokenStatusShape,
  sessionDurationMins: number,
): string {
  const remaining = status.budget - status.tokens;
  const percentUsed = Math.round(status.percent * 100);
  const bar = buildProgressBar(percentUsed);

  let response = `🐘 Token Status\n`;
  response += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  response += `${bar} ${percentUsed}%\n`;
  response += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  response += `Used: ${status.tokens.toLocaleString()} tokens\n`;
  response += `Budget: ${status.budget.toLocaleString()} tokens\n`;
  response += `Remaining: ${remaining.toLocaleString()} tokens\n`;
  response += `Session: ${sessionDurationMins} min\n`;
  response += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  response += status.alert
    ? `⚠️ ALERT: ${percentUsed}% used - Consider new session`
    : `✓ Context window healthy`;
  return response;
}

export function formatResetTokenSessionText(
  previousTokens: <REDACTED>
  budget: number,
): string {
  let response = `🐘 Token Session Reset\n`;
  response += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  response += `Previous: ${previousTokens.toLocaleString()} tokens\n`;
  response += `Current: 0 tokens\n`;
  response += `Budget: ${budget.toLocaleString()} tokens\n`;
  response += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  response += `✓ Counter cleared`;
  return response;
}

export function normalizeLimit(
  value: number | undefined,
  maxLimit = 250,
): number {
  const raw = value ?? 10;
  return Math.max(1, Math.min(maxLimit, Math.floor(raw)));
}

export function shouldAppendProactiveContext(toolName: string): boolean {
  return !PROACTIVE_EXCLUDED_TOOLS.has(toolName);
}

export function extractStringContextFromArgs(
  args: unknown,
  minLength = 10,
  maxLen = 1000,
): string {
  const contextParts: string[] = [];

  if (args && typeof args === "object") {
    for (const value of Object.values(args as Record<string, unknown>)) {
      if (typeof value === "string" && value.length > minLength) {
        contextParts.push(value);
      }
    }
  }

  return contextParts.join(" ").slice(0, maxLen);
}

/**
 * How the configured user id is named in the startup banner.
 *
 * Operators put email addresses in SHODH_USER_ID, so the raw value must not be
 * persisted into client logs. A prefix would leak the local-part — the very
 * thing at issue — so this reports a digest instead. The digest is
 * reproducible, so an operator can confirm which id is live:
 *
 *   echo -n "$SHODH_USER_ID" | shasum -a 256 | cut -c1-8
 *
 * NOTHING derived from userId other than the hash may appear in the return
 * value. An earlier revision included userId.length to make a trailing newline
 * visible; hashing is a taint sanitiser and .length is not, so that single
 * expression reintroduced a js/clear-text-logging finding (caught by
 * differential scan). The digest already changes on a trailing newline, so the
 * length bought nothing.
 *
 * This is obfuscation, not anonymisation: against a low-entropy input a reader
 * holding a candidate list can confirm a guess. It defeats incidental
 * disclosure in a shared log, which is the threat being addressed.
 */
export function describeUserId(userId: string): string {
  if (userId === "claude-code") return "claude-code";
  const digest = crypto.createHash("sha256").update(userId).digest("hex").slice(0, 8);
  return `custom (sha256:${digest})`;
}

import { createHmac, randomBytes, randomUUID, timingSafeEqual } from "node:crypto";
import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { createConnection, type Socket } from "node:net";
import { TextDecoder } from "node:util";

export const IPC_PROTOCOL_VERSION = 2;
export const IPC_MAX_FRAME_BYTES = 8 * 1024 * 1024;

const RESPONSE_FIELDS = ["auth", "body", "id", "status", "v"];
const utf8Decoder = new TextDecoder("utf-8", { fatal: true });
const WINDOWS_HELPER_LIMIT = 4;
const NONCE_BYTES = 32;
const PROBE_RESPONSE_DOMAIN = Buffer.from("shodh-ipc-v2/server-proof", "utf8");
const REQUEST_DOMAIN = Buffer.from("shodh-ipc-v2/request", "utf8");
const RESPONSE_DOMAIN = Buffer.from("shodh-ipc-v2/response", "utf8");
let activeWindowsHelpers = 0;
const windowsHelperWaiters: Array<() => void> = [];

export interface WindowsIpcHelper {
  command: string;
  args: string[];
}

interface IpcRequestEnvelope {
  v: number;
  id: string;
  auth: string;
  challenge: string;
  method: string;
  path: string;
  body: unknown;
}

interface IpcResponseEnvelope {
  v: number;
  id: string;
  auth: string;
  status: number;
  body: unknown;
}

export class IpcApiError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(status: number, body: unknown) {
    super(`API error ${status}: ${formatBody(body)}`);
    this.name = "IpcApiError";
    this.status = status;
    this.body = body;
  }
}

/** One-request-per-connection client for Shodh's authenticated local IPC protocol. */
export class ShodhIpcClient {
  readonly endpoint: string;
  readonly #apiKey: <REDACTED>
  readonly #windowsHelper?: WindowsIpcHelper;
  #serverNonce: Buffer | null = null;

  constructor(endpoint: string, apiKey: <REDACTED> windowsHelper?: WindowsIpcHelper) {
    if (!endpoint) {
      throw new Error("Shodh IPC endpoint must not be empty");
    }
    // A `\\.\pipe\` endpoint is a Windows named pipe. On any other platform it is
    // a single-component relative path that createConnection cannot open; fail loudly
    // here rather than forwarding a bogus path to an auto-spawned server that then
    // dies silently. (This catches the cross-platform quickstart being copied as-is.)
    if (process.platform !== "win32" && endpoint.startsWith("\\\\.\\pipe\\")) {
      throw new Error(
        `Shodh IPC endpoint "${endpoint}" is a Windows named pipe, but this platform ` +
          `is ${process.platform}. Set SHODH_IPC_ENDPOINT to a Unix socket path.`,
      );
    }
    if (process.platform === "win32" && !windowsHelper) {
      throw new Error("Shodh IPC on Windows requires the bundled Rust pipe helper");
    }
    this.endpoint = endpoint;
    this.#apiKey = <REDACTED>
    this.#windowsHelper = windowsHelper;
  }

  async request<T>(
    path: string,
    method = "GET",
    body: unknown = null,
    timeoutMs = 10_000,
  ): Promise<T> {
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      throw new Error("Shodh IPC timeout must be a positive number");
    }

    const expiresAt = Date.now() + timeoutMs;
    if (method === "GET" && path === "/health") {
      return await this.#probe(expiresAt) as T;
    }
    const normalizedBody = normalizeBody(body ?? null);
    const bodyJson = JSON.stringify(normalizedBody);
    const id = randomUUID();
    const sizingNonce = this.#serverNonce ?? Buffer.alloc(NONCE_BYTES);
    const sizingAuth = requestAuth(
      this.#apiKey,
      sizingNonce,
      id,
      method,
      path,
      Buffer.from(bodyJson, "utf8"),
    );
    encodeRequest({
      v: IPC_PROTOCOL_VERSION,
      id,
      auth: sizingAuth,
      challenge: "",
      method,
      path,
      body: normalizedBody,
    });
    if (!this.#serverNonce) {
      await this.#probe(expiresAt);
    }

    const auth = requestAuth(
      this.#apiKey,
      this.#serverNonce!,
      id,
      method,
      path,
      Buffer.from(bodyJson, "utf8"),
    );
    const request: IpcRequestEnvelope = {
      v: IPC_PROTOCOL_VERSION,
      id,
      auth,
      challenge: "",
      method,
      path,
      body: normalizedBody,
    };
    const encoded = encodeRequest(request);

    const response = await exchange(
      this.endpoint,
      encoded,
      remainingMs(expiresAt),
      this.#windowsHelper,
    );
    const envelope = decodeResponse(response, id);
    verifyResponse(this.#apiKey, this.#serverNonce!, auth, envelope);
    if (envelope.status < 200 || envelope.status >= 300) {
      throw new IpcApiError(envelope.status, envelope.body);
    }
    return envelope.body as T;
  }

  async #probe(expiresAt: number): Promise<unknown> {
    const id = randomUUID();
    const challenge = randomBytes(NONCE_BYTES).toString("hex");
    const request: IpcRequestEnvelope = {
      v: IPC_PROTOCOL_VERSION,
      id,
      auth: "",
      challenge,
      method: "GET",
      path: "/health",
      body: null,
    };
    const response = await exchange(
      this.endpoint,
      encodeRequest(request),
      remainingMs(expiresAt),
      this.#windowsHelper,
    );
    const envelope = decodeResponse(response, id);
    this.#serverNonce = verifyProbeResponse(this.#apiKey, challenge, envelope);
    if (envelope.status < 200 || envelope.status >= 300) {
      throw new IpcApiError(envelope.status, envelope.body);
    }
    return envelope.body;
  }
}

function normalizeBody(body: unknown): unknown {
  try {
    const encoded = JSON.stringify(body);
    if (encoded === undefined) return null;
    return JSON.parse(encoded) as unknown;
  } catch (error) {
    throw new Error(`Failed to encode Shodh IPC request body: ${errorMessage(error)}`);
  }
}

function remainingMs(expiresAt: number): number {
  const remaining = expiresAt - Date.now();
  if (remaining <= 0) {
    throw new Error("Shodh IPC request timed out before the exchange completed");
  }
  return remaining;
}

function requestAuth(
  key: string,
  nonce: Buffer,
  id: string,
  method: string,
  path: string,
  body: Buffer,
): string {
  const version = Buffer.alloc(2);
  version.writeUInt16BE(IPC_PROTOCOL_VERSION);
  const proof = macHex(key, REQUEST_DOMAIN, [
    nonce,
    version,
    Buffer.from(id, "utf8"),
    Buffer.from(method, "utf8"),
    Buffer.from(path, "utf8"),
    body,
  ]);
  return `request:${nonce.toString("hex")}:${proof}`;
}

function verifyProbeResponse(
  key: string,
  challenge: string,
  response: IpcResponseEnvelope,
): Buffer {
  const [kind, nonceHex, proofs, ...trailing] = response.auth.split(":");
  if (kind !== "probe" || !nonceHex || proofs === undefined || trailing.length > 0) {
    throw new Error("Shodh IPC health response did not authenticate the server");
  }
  const nonce = decodeNonce(nonceHex, "server nonce");
  const status = Buffer.alloc(2);
  status.writeUInt16BE(response.status);
  const expected = macHex(key, PROBE_RESPONSE_DOMAIN, [
    Buffer.from(response.id, "utf8"),
    Buffer.from(challenge, "utf8"),
    nonce,
    status,
  ]);
  if (!proofs.split(",").some((proof) => constantTimeHexEqual(proof, expected))) {
    throw new Error("Shodh IPC health response was not signed by the configured server");
  }
  return nonce;
}

function verifyResponse(
  key: string,
  nonce: Buffer,
  requestProof: string,
  response: IpcResponseEnvelope,
): void {
  const proof = response.auth.startsWith("response:")
    ? response.auth.slice("response:".length)
    : "";
  const status = Buffer.alloc(2);
  status.writeUInt16BE(response.status);
  const valid = verifyMac(key, RESPONSE_DOMAIN, [
    nonce,
    Buffer.from(requestProof, "utf8"),
    Buffer.from(response.id, "utf8"),
    status,
  ], proof);
  if (!valid) {
    throw new Error("Shodh IPC response server proof was invalid");
  }
}

function macHex(key: string, domain: Buffer, fields: Buffer[]): string {
  const mac = createHmac("sha256", key);
  updateMacField(mac, domain);
  for (const field of fields) updateMacField(mac, field);
  return mac.digest("hex");
}

function verifyMac(key: string, domain: Buffer, fields: Buffer[], proof: string): boolean {
  const expected = macHex(key, domain, fields);
  return constantTimeHexEqual(proof, expected);
}

function updateMacField(mac: ReturnType<typeof createHmac>, field: Buffer): void {
  const length = Buffer.alloc(8);
  length.writeBigUInt64BE(BigInt(field.byteLength));
  mac.update(length);
  mac.update(field);
}

function constantTimeHexEqual(actual: string, expected: string): boolean {
  if (!/^[0-9a-f]+$/i.test(actual) || actual.length !== expected.length) return false;
  return timingSafeEqual(Buffer.from(actual, "hex"), Buffer.from(expected, "hex"));
}

function decodeNonce(encoded: string, label: string): Buffer {
  if (!/^[0-9a-f]+$/i.test(encoded) || encoded.length !== NONCE_BYTES * 2) {
    throw new Error(`Shodh IPC response carried an invalid ${label}`);
  }
  return Buffer.from(encoded, "hex");
}

function encodeRequest(request: IpcRequestEnvelope): Buffer {
  let json: string;
  try {
    json = JSON.stringify(request);
  } catch (error) {
    throw new Error(`Failed to encode Shodh IPC request: ${errorMessage(error)}`);
  }

  const encoded = Buffer.from(`${json}\n`, "utf8");
  if (encoded.byteLength > IPC_MAX_FRAME_BYTES) {
    throw new Error(`Shodh IPC request exceeds the ${IPC_MAX_FRAME_BYTES}-byte frame limit`);
  }
  return encoded;
}

function exchange(
  endpoint: string,
  encoded: Buffer,
  timeoutMs: number,
  windowsHelper?: WindowsIpcHelper,
): Promise<Buffer> {
  return process.platform === "win32"
    ? exchangeWindowsPipe(endpoint, encoded, timeoutMs, windowsHelper!)
    : exchangeUnixSocket(endpoint, encoded, timeoutMs);
}

function exchangeWindowsPipe(
  endpoint: string,
  encoded: Buffer,
  timeoutMs: number,
  windowsHelper: WindowsIpcHelper,
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const expiresAt = Date.now() + timeoutMs;
    let settled = false;
    let response = Buffer.alloc(0);
    let diagnostics = Buffer.alloc(0);
    let helper: ChildProcessWithoutNullStreams | null = null;
    let releaseHelper: (() => void) | null = null;

    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      clearTimeout(deadline);
      if (helper && helper.exitCode === null && helper.signalCode === null) helper.kill();
      if (error) {
        reject(error);
      } else {
        const newline = response.indexOf(0x0a);
        if (newline === -1) {
          reject(new Error("Shodh IPC connection closed before a complete response frame arrived"));
        } else if (newline !== response.byteLength - 1) {
          reject(new Error("Shodh IPC response contained data after its newline-delimited frame"));
        } else {
          resolve(response.subarray(0, newline));
        }
      }
    };

    const deadline = setTimeout(() => {
      finish(new Error(`Shodh IPC request timed out after ${timeoutMs} ms`));
    }, timeoutMs);

    acquireWindowsHelper().then((release) => {
      releaseHelper = () => {
        if (!releaseHelper) return;
        releaseHelper = null;
        release();
      };
      if (settled || Date.now() >= expiresAt) {
        releaseHelper();
        finish(new Error(`Shodh IPC request timed out after ${timeoutMs} ms`));
        return;
      }
      let runningHelper: ChildProcessWithoutNullStreams;
      try {
        // The bundled Rust helper opens with SECURITY_IDENTIFICATION and verifies
        // the server account before it writes the authenticated request proof.
        runningHelper = spawn(windowsHelper.command, [
          ...windowsHelper.args,
          "--ipc-endpoint",
          endpoint,
          "--timeout-ms",
          String(Math.max(1, Math.ceil(expiresAt - Date.now()))),
        ], {
          stdio: ["pipe", "pipe", "pipe"],
          windowsHide: true,
        }) as ChildProcessWithoutNullStreams;
        helper = runningHelper;
      } catch (error) {
        releaseHelper();
        finish(new Error(`Failed to start Shodh IPC helper: ${errorMessage(error)}`));
        return;
      }

      runningHelper.stdout.on("data", (chunk: Buffer) => {
        if (settled) return;
        if (response.byteLength + chunk.byteLength > IPC_MAX_FRAME_BYTES) {
          finish(new Error(`Shodh IPC response exceeds the ${IPC_MAX_FRAME_BYTES}-byte frame limit`));
        } else {
          response = Buffer.concat([response, chunk]);
        }
      });
      runningHelper.stderr.on("data", (chunk: Buffer) => {
        if (diagnostics.byteLength < 4096) {
          diagnostics = Buffer.concat([diagnostics, chunk.subarray(0, 4096 - diagnostics.byteLength)]);
        }
      });
      runningHelper.once("error", (error) => {
        releaseHelper?.();
        finish(new Error(`Failed to start Shodh IPC helper: ${error.message}`));
      });
      runningHelper.once("close", (code) => {
        releaseHelper?.();
        if (settled) return;
        if (code !== 0) {
          const detail = diagnostics.toString("utf8").trim();
          if (detail === "FRAME_TOO_LARGE") {
            finish(new Error(`Shodh IPC response exceeds the ${IPC_MAX_FRAME_BYTES}-byte frame limit`));
          } else {
            finish(new Error(`Shodh IPC helper failed${detail ? `: ${detail}` : ""}`));
          }
        } else {
          finish();
        }
      });

      runningHelper.stdin.on("error", (error) => {
        finish(new Error(`Failed to write Shodh IPC request: ${error.message}`));
      });
      runningHelper.stdin.end(encoded);
    });
  });
}

function acquireWindowsHelper(): Promise<() => void> {
  return new Promise((resolve) => {
    const acquire = () => {
      activeWindowsHelpers += 1;
      let released = false;
      resolve(() => {
        if (released) return;
        released = true;
        activeWindowsHelpers -= 1;
        windowsHelperWaiters.shift()?.();
      });
    };
    if (activeWindowsHelpers < WINDOWS_HELPER_LIMIT) acquire();
    else windowsHelperWaiters.push(acquire);
  });
}

function exchangeUnixSocket(
  endpoint: string,
  encoded: Buffer,
  timeoutMs: number,
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    let socket: Socket | null = null;
    let settled = false;
    let response = Buffer.alloc(0);
    const controller = new AbortController();

    const finish = (error?: Error, frame?: Buffer) => {
      if (settled) return;
      settled = true;
      clearTimeout(deadline);
      controller.abort();
      socket?.destroy();
      if (error) reject(error);
      else resolve(frame!);
    };

    const deadline = setTimeout(() => {
      finish(new Error(`Shodh IPC request timed out after ${timeoutMs} ms`));
    }, timeoutMs);

    try {
      socket = createConnection({ path: endpoint, signal: controller.signal });
      socket.on("data", (chunk: Buffer) => {
        if (settled) return;
        if (response.byteLength + chunk.byteLength > IPC_MAX_FRAME_BYTES) {
          finish(new Error(`Shodh IPC response exceeds the ${IPC_MAX_FRAME_BYTES}-byte frame limit`));
          return;
        }
        response = Buffer.concat([response, chunk]);
        const newline = response.indexOf(0x0a);
        if (newline !== -1 && newline !== response.byteLength - 1) {
          finish(new Error("Shodh IPC response contained data after its newline-delimited frame"));
        }
      });
      socket.once("connect", () => {
        socket?.write(encoded, (error) => {
          if (error) finish(new Error(`Failed to write Shodh IPC request: ${error.message}`));
        });
      });
      socket.once("end", () => {
        if (settled) return;
        const newline = response.indexOf(0x0a);
        if (newline === -1) {
          finish(new Error("Shodh IPC connection closed before a complete response frame arrived"));
        } else {
          finish(undefined, response.subarray(0, newline));
        }
      });
      socket.once("error", (error) => {
        finish(new Error(`Shodh IPC connection failed: ${error.message}`));
      });
    } catch (error) {
      finish(new Error(`Failed to connect to Shodh IPC: ${errorMessage(error)}`));
    }
  });
}

function decodeResponse(frame: Buffer, expectedId: string): IpcResponseEnvelope {
  let text: string;
  try {
    text = utf8Decoder.decode(frame);
  } catch {
    throw new Error("Shodh IPC response was not valid UTF-8");
  }

  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch (error) {
    throw new Error(`Shodh IPC response was not valid JSON: ${errorMessage(error)}`);
  }

  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Shodh IPC response must be a JSON object");
  }
  const record = value as Record<string, unknown>;
  const fields = Object.keys(record).sort();
  if (fields.length !== RESPONSE_FIELDS.length || fields.some((field, index) => field !== RESPONSE_FIELDS[index])) {
    throw new Error("Shodh IPC response fields did not match the version two envelope");
  }
  if (record.v !== IPC_PROTOCOL_VERSION) {
    throw new Error(`Unsupported Shodh IPC response version ${String(record.v)}`);
  }
  // An empty id is how the server reports a protocol error it hit before (or while)
  // parsing the request envelope — it has no correlation id to echo. Treat it as a
  // server error to surface via the status check below, NOT as an id mismatch, so
  // the real status/message reaches the caller instead of being masked.
  if (typeof record.id !== "string" || (record.id !== "" && record.id !== expectedId)) {
    throw new Error("Shodh IPC response request ID did not match");
  }
  if (typeof record.auth !== "string") {
    throw new Error("Shodh IPC response authentication proof was invalid");
  }
  if (!Number.isInteger(record.status) || (record.status as number) < 100 || (record.status as number) > 599) {
    throw new Error("Shodh IPC response status was invalid");
  }

  return record as unknown as IpcResponseEnvelope;
}

function formatBody(body: unknown): string {
  if (typeof body === "string") return body;
  try {
    return JSON.stringify(body) ?? "null";
  } catch {
    return "unreadable error response";
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function isLocalHostFromUrl(apiUrl: string): boolean {
  try {
    const url = new URL(apiUrl);
    const host = url.hostname;
    return host === "127.0.0.1" || host === "localhost" || host === "::1" || host === "0.0.0.0";
  } catch {
    return false;
  }
}

export function shouldWarnInsecureApiUrl(apiUrl: string, allowHttpEnv?: string): boolean {
  return !isLocalHostFromUrl(apiUrl) && apiUrl.startsWith("http://") && allowHttpEnv !== "true";
}

export function serializeAndValidateBody(body: object, maxLength: number): { ok: true; serialized: string } | { ok: false; error: string } {
  const serialized = JSON.stringify(body);
  if (serialized.length > maxLength) {
    return { ok: false, error: `Request body exceeds maximum length of ${maxLength} characters` };
  }
  return { ok: true, serialized };
}

export function nextReconnectDelay(currentDelayMs: number, maxDelayMs: number): number {
  const safeCurrent = Math.max(currentDelayMs, 1000);
  return Math.min(safeCurrent * 2, maxDelayMs);
}

