import { describe, expect, it, beforeEach, afterEach, beforeAll } from "vitest";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import { spawnSync } from "child_process";
import {
  SERVER_PIDFILE,
  SHIM_PID_DIR,
  backendPidToReap,
  clearSpawnedServer,
  isPidAlive,
  liveSiblingShims,
  readSpawnedServerPid,
  recordSpawnedServer,
  registerShim,
  unregisterShim,
} from "../backend-lifecycle";

let tmpRoot: string;
// A pid that definitely existed and is definitely dead now (short-lived child).
let deadPid: number;

beforeAll(() => {
  const child = spawnSync(process.execPath, ["-e", ""], { stdio: "ignore" });
  if (child.pid === undefined) throw new Error("failed to spawn probe child");
  deadPid = child.pid;
});

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "shodh-lifecycle-test-"));
});

afterEach(() => {
  fs.rmSync(tmpRoot, { recursive: true, force: true });
});

describe("isPidAlive", () => {
  it("is true for the current process and false for a dead pid", () => {
    expect(isPidAlive(process.pid)).toBe(true);
    expect(isPidAlive(deadPid)).toBe(false);
  });

  it("rejects garbage pids", () => {
    expect(isPidAlive(0)).toBe(false);
    expect(isPidAlive(-5)).toBe(false);
    expect(isPidAlive(1.5)).toBe(false);
  });
});

describe("shim registration", () => {
  it("registers and unregisters a pidfile", () => {
    const file = registerShim(tmpRoot, process.pid);
    expect(file).toBe(path.join(tmpRoot, SHIM_PID_DIR, `${process.pid}.pid`));
    expect(fs.existsSync(file)).toBe(true);
    unregisterShim(tmpRoot, process.pid);
    expect(fs.existsSync(file)).toBe(false);
  });

  it("unregister is safe when never registered", () => {
    expect(() => unregisterShim(tmpRoot, 12345)).not.toThrow();
  });
});

describe("liveSiblingShims", () => {
  it("excludes self and prunes dead registrations", () => {
    registerShim(tmpRoot, process.pid); // self
    registerShim(tmpRoot, deadPid); // crashed shim
    const siblings = liveSiblingShims(tmpRoot, process.pid);
    expect(siblings).toEqual([]);
    // The dead shim's stale file must have been pruned.
    expect(fs.existsSync(path.join(tmpRoot, SHIM_PID_DIR, `${deadPid}.pid`))).toBe(false);
  });

  it("reports a live sibling", () => {
    // Register our own (live) pid, then ask from the perspective of another shim.
    registerShim(tmpRoot, process.pid);
    const siblings = liveSiblingShims(tmpRoot, deadPid);
    expect(siblings).toEqual([process.pid]);
  });

  it("returns empty when the directory does not exist", () => {
    expect(liveSiblingShims(tmpRoot, process.pid)).toEqual([]);
  });

  it("prunes unparseable entries", () => {
    fs.mkdirSync(path.join(tmpRoot, SHIM_PID_DIR), { recursive: true });
    fs.writeFileSync(path.join(tmpRoot, SHIM_PID_DIR, "garbage.txt"), "x");
    expect(liveSiblingShims(tmpRoot, process.pid)).toEqual([]);
    expect(fs.existsSync(path.join(tmpRoot, SHIM_PID_DIR, "garbage.txt"))).toBe(false);
  });
});

describe("spawned server record", () => {
  it("records and reads the backend pid", () => {
    recordSpawnedServer(tmpRoot, 4242);
    expect(readSpawnedServerPid(tmpRoot)).toBe(4242);
    clearSpawnedServer(tmpRoot);
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });

  it("does not clobber a live backend's record (concurrent-spawn loser)", () => {
    recordSpawnedServer(tmpRoot, process.pid); // "live" backend
    recordSpawnedServer(tmpRoot, 99999999); // loser tries to record its dead child
    expect(readSpawnedServerPid(tmpRoot)).toBe(process.pid);
  });

  it("replaces a dead backend's record", () => {
    recordSpawnedServer(tmpRoot, deadPid);
    recordSpawnedServer(tmpRoot, process.pid);
    expect(readSpawnedServerPid(tmpRoot)).toBe(process.pid);
  });

  it("readSpawnedServerPid rejects garbage content", () => {
    fs.writeFileSync(path.join(tmpRoot, SERVER_PIDFILE), "not-a-pid\n");
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });
});

describe("backendPidToReap — the T14 kill decision", () => {
  it("never kills while another live shim is registered", () => {
    recordSpawnedServer(tmpRoot, process.pid); // pretend backend is alive
    registerShim(tmpRoot, process.pid); // a live sibling (our own pid, seen from selfPid=deadPid)
    expect(backendPidToReap(tmpRoot, deadPid)).toBeNull();
  });

  it("returns the backend pid when this is the last shim", () => {
    recordSpawnedServer(tmpRoot, process.pid);
    expect(backendPidToReap(tmpRoot, process.pid)).toBe(process.pid);
  });

  it("returns null when no backend was auto-spawned (manual servers are never killed)", () => {
    expect(backendPidToReap(tmpRoot, process.pid)).toBeNull();
  });

  it("clears the record and returns null when the backend already died", () => {
    recordSpawnedServer(tmpRoot, deadPid);
    expect(backendPidToReap(tmpRoot, process.pid)).toBeNull();
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });

  it("ignores stale registrations from crashed shims", () => {
    recordSpawnedServer(tmpRoot, process.pid);
    registerShim(tmpRoot, deadPid); // crashed shim never unregistered
    expect(backendPidToReap(tmpRoot, process.pid)).toBe(process.pid);
  });
});

import { describe, it, expect } from "vitest";
import {
  renderCommandsResource,
  firstSentence,
  TOOL_GROUPS,
  type CommandsTool,
  type CommandsPrompt,
} from "../commands-resource";

const tool = (name: string, description = `Does ${name}. And more detail here.`): CommandsTool => ({
  name,
  description,
});

/** Every tool named in TOOL_GROUPS, which is what the real server passes in. */
const allGroupedTools = (): CommandsTool[] =>
  TOOL_GROUPS.flatMap(([, names]) => names.map((n) => tool(n)));

const prompts: CommandsPrompt[] = [
  { name: "quick_recall", description: "Search your memories for relevant context" },
];

describe("firstSentence", () => {
  it("takes the first sentence of a multi-sentence description", () => {
    expect(firstSentence("Store a memory. Use this for decisions.")).toBe("Store a memory.");
  });

  it("returns the whole string when there is no terminator", () => {
    expect(firstSentence("List all stored memories")).toBe("List all stored memories");
  });

  it("does not split on a decimal point or an abbreviation mid-sentence", () => {
    expect(firstSentence("Defaults to 2.0 sigma and ranks. Then stops.")).toBe(
      "Defaults to 2.0 sigma and ranks.",
    );
  });
});

describe("renderCommandsResource", () => {
  it("lists every declared tool exactly once", () => {
    const tools = allGroupedTools();
    const md = renderCommandsResource(tools, prompts);
    for (const t of tools) {
      const occurrences = md.split(`- **${t.name}** —`).length - 1;
      expect(occurrences, `tool ${t.name} should appear exactly once`).toBe(1);
    }
  });

  it("names no tool that is not declared", () => {
    const tools = allGroupedTools();
    const declared = new Set(tools.map((t) => t.name));
    const md = renderCommandsResource(tools, prompts);
    const listed = [...md.matchAll(/^- \*\*([a-z_]+)\*\* —/gm)]
      .map((m) => m[1])
      .filter((n) => !n.startsWith("/"));
    for (const name of listed) {
      expect(declared.has(name), `${name} is listed but not declared`).toBe(true);
    }
  });

  it("throws when a declared tool has no group, naming the tool", () => {
    const tools = [...allGroupedTools(), tool("brand_new_tool")];
    expect(() => renderCommandsResource(tools, prompts)).toThrow(/brand_new_tool/);
  });

  it("throws when a group names a tool that no longer exists", () => {
    const tools = allGroupedTools().filter((t) => t.name !== "recall");
    expect(() => renderCommandsResource(tools, prompts)).toThrow(/recall/);
  });

  it("renders prompts as slash commands", () => {
    const md = renderCommandsResource(allGroupedTools(), prompts);
    expect(md).toContain("/mcp__shodh-memory__quick_recall");
  });

  it("reports the real tool and prompt counts", () => {
    const tools = allGroupedTools();
    const md = renderCommandsResource(tools, prompts);
    expect(md).toContain(`${tools.length} tools and ${prompts.length} prompts`);
  });

  it("assigns each tool to exactly one group", () => {
    const seen = new Set<string>();
    for (const [, names] of TOOL_GROUPS) {
      for (const name of names) {
        expect(seen.has(name), `${name} appears in two groups`).toBe(false);
        seen.add(name);
      }
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  TOOL_ANNOTATIONS,
  TOOL_OUTPUT_SCHEMAS,
  READ_ONLY_TOOLS,
  isReadOnlyTool,
  decorateTool,
  type ToolDefinition,
} from "../tool-metadata";

const def = (name: string): ToolDefinition => ({
  name,
  description: "d",
  inputSchema: { type: "object", properties: {} },
});

describe("tool annotations", () => {
  it("covers every tool exactly once", () => {
    // The server declares 51 tools; decorateTool throws for anything missing,
    // so this count is the tripwire for a tool added without a judgement call.
    expect(Object.keys(TOOL_ANNOTATIONS)).toHaveLength(51);
  });

  it("gives every tool a display title", () => {
    for (const [name, ann] of Object.entries(TOOL_ANNOTATIONS)) {
      expect(ann.title, `${name} has no title`).toBeTruthy();
    }
  });

  it("closes the world for every tool", () => {
    // The memory store is local and closed. The spec default is TRUE, so this
    // must be set explicitly everywhere or clients assume external reach.
    for (const [name, ann] of Object.entries(TOOL_ANNOTATIONS)) {
      expect(ann.openWorldHint, `${name} should be closed-world`).toBe(false);
    }
  });

  it("sets destructive and idempotent explicitly on every mutating tool", () => {
    // destructiveHint defaults to TRUE when absent, so an unset hint on an
    // additive tool would wrongly mark it dangerous.
    for (const [name, ann] of Object.entries(TOOL_ANNOTATIONS)) {
      if (ann.readOnlyHint) continue;
      expect(typeof ann.destructiveHint, `${name} destructiveHint`).toBe("boolean");
      expect(typeof ann.idempotentHint, `${name} idempotentHint`).toBe("boolean");
    }
  });

  it("omits destructive/idempotent on read-only tools", () => {
    // The spec defines both as meaningful only when readOnlyHint is false.
    for (const [name, ann] of Object.entries(TOOL_ANNOTATIONS)) {
      if (!ann.readOnlyHint) continue;
      expect(ann.destructiveHint, `${name} destructiveHint`).toBeUndefined();
      expect(ann.idempotentHint, `${name} idempotentHint`).toBeUndefined();
    }
  });

  it("keeps isReadOnlyTool in sync with the annotations", () => {
    for (const [name, ann] of Object.entries(TOOL_ANNOTATIONS)) {
      expect(isReadOnlyTool(name)).toBe(Boolean(ann.readOnlyHint));
    }
    expect(READ_ONLY_TOOLS.size).toBe(
      Object.values(TOOL_ANNOTATIONS).filter((a) => a.readOnlyHint).length,
    );
  });
});

describe("data-loss hazard tools are never marked safe", () => {
  // Regression guard. A client that auto-approves readOnlyHint:true tools must
  // never be handed one of these. Flipping any of them to read-only is a
  // data-loss hazard, not a refactor.
  const mustBeDestructive = [
    "forget",
    "purge_facts",
    "delete_todo",
    "delete_project",
    "delete_todo_comment",
    "backup_purge",
    "backup_restore",
    "validate_causal_link",
    "update_todo",
    "update_todo_comment",
  ];

  for (const name of mustBeDestructive) {
    it(`${name} is destructive and not read-only`, () => {
      const ann = TOOL_ANNOTATIONS[name];
      expect(ann).toBeDefined();
      expect(ann.readOnlyHint).toBe(false);
      expect(ann.destructiveHint).toBe(true);
      expect(isReadOnlyTool(name)).toBe(false);
    });
  }

  // Names that read like queries but write. Verified against the handlers:
  // proactive_context defaults to auto_ingest:true, reset_token_session
  // persists a session-digest Context memory, repair_index re-indexes.
  const writesDespiteName = ["proactive_context", "reset_token_session", "repair_index"];

  for (const name of writesDespiteName) {
    it(`${name} writes despite its name`, () => {
      expect(TOOL_ANNOTATIONS[name].readOnlyHint).toBe(false);
      expect(isReadOnlyTool(name)).toBe(false);
    });
  }

  it("marks non-idempotent writers honestly", () => {
    // complete_todo re-completes and spawns another recurrence + memory;
    // add_project mints a fresh UUID; add_causal_link reinforces on repeat;
    // reinforce_memories compounds boosts.
    for (const name of ["complete_todo", "add_project", "add_causal_link", "reinforce_memories", "backup_create"]) {
      expect(TOOL_ANNOTATIONS[name].idempotentHint, name).toBe(false);
    }
  });
});

describe("output schemas", () => {
  it("declares an object at the root, as the spec requires", () => {
    for (const [name, schema] of Object.entries(TOOL_OUTPUT_SCHEMAS)) {
      expect(schema.type, `${name} root type`).toBe("object");
      expect(schema.properties, `${name} properties`).toBeTruthy();
    }
  });

  it("only lists required keys that the schema declares", () => {
    for (const [name, schema] of Object.entries(TOOL_OUTPUT_SCHEMAS)) {
      for (const key of schema.required ?? []) {
        expect(Object.keys(schema.properties ?? {}), `${name}.${key}`).toContain(key);
      }
    }
  });

  it("only schemas tools that exist", () => {
    for (const name of Object.keys(TOOL_OUTPUT_SCHEMAS)) {
      expect(TOOL_ANNOTATIONS[name], `${name} has a schema but no annotation`).toBeDefined();
    }
  });
});

describe("decorateTool", () => {
  it("attaches annotations", () => {
    const decorated = decorateTool(def("recall"));
    expect(decorated.annotations.readOnlyHint).toBe(true);
    expect(decorated.annotations.title).toBe("Recall Memories & Todos");
  });

  it("attaches an outputSchema only where one is declared", () => {
    expect(decorateTool(def("recall")).outputSchema).toBeDefined();
    // A one-line confirmation gains nothing from a schema.
    expect(decorateTool(def("forget")).outputSchema).toBeUndefined();
  });

  it("throws for an unannotated tool rather than defaulting silently", () => {
    // A silent default would ship the spec defaults (destructive + open world)
    // AND would leave the tool outside the ambient-ingestion gate.
    expect(() => decorateTool(def("brand_new_tool"))).toThrow(/no entry in TOOL_BEHAVIOUR/);
  });

  it("does not mutate the input definition", () => {
    const original = def("recall");
    decorateTool(original);
    expect("annotations" in original).toBe(false);
  });
});

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { RefreshCw } from "lucide-react";
import { cn } from "@/lib/utils";
import { listMcpServers, reconnectMcpServer } from "@/lib/seat/client";
import type { McpServerInfo } from "@/lib/seat/types";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { InfoHint } from "@/components/ui/info-hint";
import { Meta, Stat } from "@/components/ui/meta";

/**
 * The tool servers the seat is connected to, on the same screen as the model
 * endpoints it can call.
 *
 * WHY IT LIVES HERE. Both halves of this screen answer one question — what can
 * my agent reach? — and they were only ever separable to an implementer.
 * Providers decide which models can think; these decide which tools they can
 * act with. Splitting them into two destinations would make a person check two
 * places to answer one question, so this is a section, not a route.
 *
 * WHAT IT REFUSES TO IMPLY. A tool listed here has been NAMED by its server,
 * not called by anything. The seat lists tools at connect time and again
 * whenever a server announces its list changed; it has no idea whether any of
 * them work. That caveat is visible copy rather than something inside the info
 * panel, because most people never open info panels and this one changes how
 * the numbers on screen should be read.
 */

/** Failure states are not interchangeable and the colour says which is which.
 *  A server that dropped was working a moment ago and usually comes back on a
 *  reconnect — that is the amber "look at this", not the red "this is broken".
 *  A server that never came up needs its configuration fixed first. */
function StatusDot({ status }: { status: McpServerInfo["status"] }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "size-1.5 shrink-0 rounded-full",
        status === "ready" && "bg-[var(--live)]",
        status === "connecting" && "bg-muted-foreground/40 animate-pulse",
        status === "disconnected" && "bg-warn",
        status === "failed" && "bg-destructive",
      )}
    />
  );
}

/** Where the server runs, in the words someone would use to describe it —
 *  never the transport enum on its own. "sse" earns its extra token because a
 *  server on the superseded transport is a thing worth knowing about when it
 *  eventually stops working. */
function whereItRuns(server: McpServerInfo): string {
  if (server.transport === "stdio") return "on this machine";
  return server.transport === "sse" ? "remote · older transport" : "remote";
}

function statusWord(server: McpServerInfo): string | null {
  switch (server.status) {
    case "ready":
      return null;
    case "connecting":
      return "connecting";
    case "disconnected":
      return "connection dropped";
    case "failed":
      return server.connected_at ? "reconnect failed" : "never connected";
  }
}

function ServerRow({ server }: { server: McpServerInfo }) {
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);

  const reconnect = useMutation({
    mutationFn: () => reconnectMcpServer(server.name),
    onSuccess: (updated) => {
      queryClient.setQueryData<{ servers: McpServerInfo[] }>(["seat-mcp-servers"], (old) =>
        old
          ? { servers: old.servers.map((s) => (s.name === updated.name ? updated : s)) }
          : old,
      );
    },
  });

  // A server that has never been up is being CONNECTED, not re-connected. Small
  // thing, but the wrong word here reads as "this used to work", which sends
  // someone looking for what changed instead of at their configuration.
  const actionLabel = server.connected_at ? "Reconnect" : "Connect";
  const status = statusWord(server);
  const address = server.endpoint ?? server.command;

  return (
    <div className="border-border border-b px-4 py-2.5">
      <div className="flex items-center gap-2.5">
        <StatusDot status={server.status} />
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          disabled={server.tools.length === 0}
          className="focus-visible:ring-ring min-w-0 flex-1 truncate text-left text-[13px] focus-visible:ring-2 focus-visible:outline-none disabled:cursor-default"
        >
          {server.tools.length > 0 ? (
            <span aria-hidden="true" className="text-muted-foreground/50 mr-1">
              {open ? "▾" : "▸"}
            </span>
          ) : null}
          {server.name}
        </button>
        <Badge className="mono shrink-0">{whereItRuns(server)}</Badge>
        <Meta className="shrink-0">
          {server.status === "ready" || server.tool_count > 0 ? (
            <Stat value={server.tool_count} label={server.tool_count === 1 ? "tool" : "tools"} />
          ) : null}
          {status ? (
            <span
              className={cn(
                server.status === "failed" && "text-destructive",
                server.status === "disconnected" && "text-warn",
              )}
            >
              {status}
            </span>
          ) : null}
        </Meta>
        <Button
          size="sm"
          variant="ghost"
          disabled={reconnect.isPending || server.status === "connecting"}
          onClick={() => reconnect.mutate()}
          aria-label={`${actionLabel} ${server.name}`}
        >
          <RefreshCw className={cn(reconnect.isPending && "animate-spin")} />
          {actionLabel}
        </Button>
      </div>

      {address ? (
        <p className="text-muted-foreground/70 mono mt-1 truncate pl-4 text-[10px]" title={address}>
          {address}
          {server.auth_header_names.length > 0
            ? ` · sends ${server.auth_header_names.join(", ")}`
            : null}
        </p>
      ) : null}

      {/* The seat's own words for what went wrong, verbatim. A stdio server's
          last output can run to a stack trace, so it scrolls rather than
          pushing every other server off the screen. It carries the same colour
          as the status word above it — a dropped server is amber in both
          places, because a reason box in alarm red beside an amber status
          reads as two different verdicts on one server. */}
      {server.error ? (
        <pre
          className={cn(
            "mono mt-1.5 ml-4 max-h-24 overflow-auto rounded border p-2 text-[11px] leading-relaxed whitespace-pre-wrap",
            server.status === "disconnected"
              ? "text-warn border-warn/30 bg-warn/5"
              : "text-destructive border-destructive/20 bg-destructive/5",
          )}
        >
          {server.error}
        </pre>
      ) : null}

      {reconnect.isError ? (
        <p className="text-destructive mt-1 pl-4 text-[11px]">
          {reconnect.error instanceof Error ? reconnect.error.message : "Could not reach the seat."}
        </p>
      ) : null}

      {open && server.tools.length > 0 ? (
        <ul className="mt-2 ml-4 space-y-1">
          {server.tools.map((tool) => (
            <li key={tool.name} className="flex min-w-0 items-baseline gap-2">
              <span className="mono text-foreground/85 shrink-0 text-[11px]">{tool.name}</span>
              {tool.description ? (
                <span className="text-muted-foreground min-w-0 flex-1 truncate text-[11px]" title={tool.description}>
                  {tool.description}
                </span>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

export function McpServers() {
  const query = useQuery({
    queryKey: ["seat-mcp-servers"],
    queryFn: ({ signal }) => listMcpServers(signal),
    staleTime: 10_000,
    // A server can go away without anyone touching this screen — the seat
    // notices immediately, and a poll this cheap (a local process, a few
    // hundred bytes) is what carries that to the page someone is already
    // looking at. There is no push channel for it and inventing one for a
    // status list would be a lot of machinery for a 15-second delay.
    refetchInterval: 15_000,
  });

  const servers = query.data?.servers ?? [];
  const connected = servers.filter((server) => server.status === "ready");
  const reachableTools = connected.reduce((total, server) => total + server.tool_count, 0);
  const down = servers.length - connected.length;

  return (
    <section aria-labelledby="mcp-servers-heading">
      <div className="border-border flex items-center gap-1.5 border-b px-4 pt-6 pb-1">
        <h3
          id="mcp-servers-heading"
          className="text-muted-foreground/70 text-[10px] tracking-wide uppercase"
        >
          Tool servers{query.data ? ` (${servers.length})` : ""}
        </h3>
        <InfoHint label="Tool servers">
          Programs and endpoints that publish tools your agent can call — files,
          issue trackers, this memory itself. The seat starts the local ones and
          dials the remote ones, then offers their tools to the model under
          names like <span className="mono">mcp__shodh-memory__recall</span>.
          <br />
          <br />
          Access tokens for a remote server stay in the seat process; this page
          only ever names the headers being sent, never their contents.
          <br />
          <br />
          Nothing reconnects itself. A server that dropped stays visible and
          stays down until you reconnect it here — a background retry loop
          would hide the failure and hammer a server that is genuinely broken.
        </InfoHint>
      </div>

      {/* Three states that look identical if you only ever read `data`, and
          two of them are statements about the user's configuration that would
          be FALSE: a request still in flight, and a request that failed. The
          latter is the worse one — it persists, and it tells someone their
          servers are not configured when in truth the seat could not be
          asked. Kept apart, in the idiom the provider list above already
          uses. */}
      {query.isPending ? (
        <p className="text-muted-foreground border-border border-b px-4 py-3 text-[12px]">
          Listing tool servers…
        </p>
      ) : query.isError ? (
        <p className="text-destructive border-border border-b px-4 py-3 text-[12px] leading-relaxed">
          Could not ask the seat which tool servers it has
          {query.error instanceof Error ? `: ${query.error.message}` : "."} This
          says nothing about the servers themselves — they may well be
          connected.
        </p>
      ) : servers.length === 0 ? (
        <p className="text-muted-foreground border-border border-b px-4 py-3 text-[12px] leading-relaxed">
          No tool servers are configured. The seat reads them from the JSON file
          named by <span className="mono">SEAT_MCP_SERVERS</span> — a command to
          run for a server on this machine, or a URL for one hosted elsewhere.
        </p>
      ) : (
        <>
          <div className="border-border border-b px-4 py-2">
            <Meta>
              <Stat value={connected.length} label={`of ${servers.length} connected`} />
              <Stat value={reachableTools} label="tools reachable" />
              {down > 0 ? <span className="text-warn">{down} unavailable</span> : null}
            </Meta>
            {/* On screen, not in the info panel: it changes how the tool counts
                above should be read, and info panels mostly go unopened. */}
            <p className="text-muted-foreground/70 mt-1 text-[11px] leading-relaxed">
              Tools are listed as each server describes them. The seat has not
              called them.
            </p>
          </div>
          {servers.map((server) => (
            <ServerRow key={server.name} server={server} />
          ))}
        </>
      )}
    </section>
  );
}

