//! Circuit breaker pattern for embedding service resilience
//!
//! Implements a production-grade circuit breaker to prevent cascading failures
//! when the ONNX embedding service is degraded or unavailable.
//!
//! # States
//! - **Closed**: Normal operation, requests pass through
//! - **Open**: Service is failing, requests are rejected immediately
//! - **HalfOpen**: Testing if service has recovered
//!
//! # Configuration
//! - `failure_threshold`: Number of failures before opening (default: 5)
//! - `success_threshold`: Successes needed to close from half-open (default: 2)
//! - `open_duration`: Time circuit stays open before testing (default: 30s)
//!
//! # Metrics Integration
//! All state transitions and rejections are tracked via Prometheus metrics.

use anyhow::Result;
use parking_lot::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use super::{minilm::MiniLMEmbedder, Embedder};

/// Circuit breaker states
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CircuitState {
    /// Normal operation - requests pass through
    Closed,
    /// Service is failing - requests rejected immediately
    Open,
    /// Testing recovery - limited requests allowed
    HalfOpen,
}

impl std::fmt::Display for CircuitState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CircuitState::Closed => write!(f, "closed"),
            CircuitState::Open => write!(f, "open"),
            CircuitState::HalfOpen => write!(f, "half_open"),
        }
    }
}

/// Circuit breaker configuration
#[derive(Debug, Clone)]
pub struct CircuitBreakerConfig {
    /// Number of consecutive failures before opening the circuit
    pub failure_threshold: u32,
    /// Number of consecutive successes needed to close from half-open
    pub success_threshold: u32,
    /// Duration the circuit stays open before transitioning to half-open
    pub open_duration: Duration,
    /// Maximum time to wait for a single embedding operation
    pub call_timeout: Duration,
}

impl Default for CircuitBreakerConfig {
    fn default() -> Self {
        Self {
            failure_threshold: 5,
            success_threshold: 2,
            open_duration: Duration::from_secs(30),
            call_timeout: Duration::from_secs(10),
        }
    }
}

/// Internal state tracking
struct CircuitBreakerState {
    state: CircuitState,
    consecutive_failures: u32,
    consecutive_successes: u32,
    last_failure_time: Option<Instant>,
    last_state_change: Instant,
}

impl CircuitBreakerState {
    fn new() -> Self {
        Self {
            state: CircuitState::Closed,
            consecutive_failures: 0,
            consecutive_successes: 0,
            last_failure_time: None,
            last_state_change: Instant::now(),
        }
    }
}

/// Circuit breaker wrapper for embedding service
///
/// Provides resilience by:
/// 1. Tracking failure rates
/// 2. Opening circuit when failures exceed threshold
/// 3. Automatically testing recovery after cooldown
/// 4. Falling back to simplified embeddings when circuit is open
pub struct ResilientEmbedder {
    inner: Arc<MiniLMEmbedder>,
    config: CircuitBreakerConfig,
    state: Mutex<CircuitBreakerState>,
    // Atomic counters for metrics (lock-free)
    total_calls: AtomicU64,
    total_rejections: AtomicU64,
    total_fallbacks: AtomicU64,
}

impl ResilientEmbedder {
    /// Create a new resilient embedder wrapping the given MiniLM embedder
    pub fn new(embedder: Arc<MiniLMEmbedder>, config: CircuitBreakerConfig) -> Self {
        Self {
            inner: embedder,
            config,
            state: Mutex::new(CircuitBreakerState::new()),
            total_calls: AtomicU64::new(0),
            total_rejections: AtomicU64::new(0),
            total_fallbacks: AtomicU64::new(0),
        }
    }

    /// Create with default configuration
    pub fn with_defaults(embedder: Arc<MiniLMEmbedder>) -> Self {
        Self::new(embedder, CircuitBreakerConfig::default())
    }

    /// Get current circuit state
    pub fn state(&self) -> CircuitState {
        self.state.lock().state
    }

    /// Get metrics for monitoring
    pub fn metrics(&self) -> CircuitBreakerMetrics {
        let state = self.state.lock();
        CircuitBreakerMetrics {
            state: state.state,
            consecutive_failures: state.consecutive_failures,
            consecutive_successes: state.consecutive_successes,
            total_calls: self.total_calls.load(Ordering::Relaxed),
            total_rejections: self.total_rejections.load(Ordering::Relaxed),
            total_fallbacks: self.total_fallbacks.load(Ordering::Relaxed),
            time_in_current_state: state.last_state_change.elapsed(),
        }
    }

    /// Check if circuit allows requests and update state if needed
    fn should_allow_request(&self) -> bool {
        let mut state = self.state.lock();

        match state.state {
            CircuitState::Closed => true,
            CircuitState::Open => {
                // Check if enough time has passed to try recovery
                if state.last_state_change.elapsed() >= self.config.open_duration {
                    tracing::info!(
                        "Circuit breaker transitioning from Open to HalfOpen after {:?}",
                        self.config.open_duration
                    );
                    state.state = CircuitState::HalfOpen;
                    state.consecutive_successes = 0;
                    state.last_state_change = Instant::now();
                    self.record_state_change(CircuitState::HalfOpen);
                    true
                } else {
                    false
                }
            }
            CircuitState::HalfOpen => true,
        }
    }

    /// Record a successful operation
    fn record_success(&self) {
        let mut state = self.state.lock();
        state.consecutive_failures = 0;
        state.consecutive_successes += 1;

        if state.state == CircuitState::HalfOpen
            && state.consecutive_successes >= self.config.success_threshold
        {
            tracing::info!(
                "Circuit breaker closing after {} consecutive successes",
                state.consecutive_successes
            );
            state.state = CircuitState::Closed;
            state.last_state_change = Instant::now();
            self.record_state_change(CircuitState::Closed);
        }
    }

    /// Record a failed operation
    fn record_failure(&self) {
        let mut state = self.state.lock();
        state.consecutive_successes = 0;
        state.consecutive_failures += 1;
        state.last_failure_time = Some(Instant::now());

        match state.state {
            CircuitState::Closed => {
                if state.consecutive_failures >= self.config.failure_threshold {
                    tracing::warn!(
                        "Circuit breaker opening after {} consecutive failures",
                        state.consecutive_failures
                    );
                    state.state = CircuitState::Open;
                    state.last_state_change = Instant::now();
                    self.record_state_change(CircuitState::Open);
                }
            }
            CircuitState::HalfOpen => {
                // Single failure in half-open returns to open
                tracing::warn!("Circuit breaker returning to Open after failure in HalfOpen state");
                state.state = CircuitState::Open;
                state.last_state_change = Instant::now();
                self.record_state_change(CircuitState::Open);
            }
            CircuitState::Open => {
                // Already open, nothing to do
            }
        }
    }

    /// Record state change to metrics
    fn record_state_change(&self, new_state: CircuitState) {
        let label1 = format!("circuit_breaker_{new_state}");
        let label2 = String::from("embedding");
        crate::metrics::ERRORS_TOTAL
            .with_label_values(&[&label1, &label2])
            .inc();
    }

    /// Generate fallback embedding using simplified hash-based approach
    fn generate_fallback(&self, text: &str) -> Vec<f32> {
        self.total_fallbacks.fetch_add(1, Ordering::Relaxed);

        // Use the same hash-based approach as simplified mode
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};

        let dimension = self.inner.dimension();
        let mut embedding = vec![0.0; dimension];

        let words: Vec<&str> = text.split_whitespace().collect();

        for (i, word) in words.iter().enumerate() {
            let mut hasher = DefaultHasher::new();
            word.hash(&mut hasher);
            let hash = hasher.finish();

            for j in 0..dimension {
                let index = (i.wrapping_mul(7) + j) % dimension;
                if j < 64 {
                    embedding[index] += ((hash >> j) & 1) as f32 * 0.1;
                } else {
                    embedding[index] += ((hash >> (j % 64)) & 1) as f32 * 0.1;
                }
            }
        }

        // Normalize
        let norm: f32 = embedding.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            for val in &mut embedding {
                *val /= norm;
            }
        }

        embedding
    }
}

impl Embedder for ResilientEmbedder {
    fn encode(&self, text: &str) -> Result<Vec<f32>> {
        self.total_calls.fetch_add(1, Ordering::Relaxed);

        if text.is_empty() {
            return Ok(vec![0.0; self.inner.dimension()]);
        }

        // Check circuit state
        if !self.should_allow_request() {
            self.total_rejections.fetch_add(1, Ordering::Relaxed);
            tracing::debug!("Circuit breaker open, using fallback embedding");
            return Ok(self.generate_fallback(text));
        }

        // Try the actual embedding
        match self.inner.encode(text) {
            Ok(embedding) => {
                self.record_success();
                Ok(embedding)
            }
            Err(e) => {
                self.record_failure();
                tracing::warn!("Embedding failed (circuit breaker tracking): {}", e);
                // Return fallback instead of error to maintain availability
                Ok(self.generate_fallback(text))
            }
        }
    }

    fn dimension(&self) -> usize {
        self.inner.dimension()
    }

    /// Token counting is a pure tokenizer operation — no inference, no
    /// circuit involved. Always forward to the inner embedder so chunk
    /// budgets stay in real-tokenizer units even when the circuit is open.
    fn count_tokens(&self, text: &str) -> usize {
        self.inner.count_tokens(text)
    }

    fn chunk_budget_tokens(&self) -> usize {
        self.inner.chunk_budget_tokens()
    }

    fn encode_batch(&self, texts: &[&str]) -> Result<Vec<Vec<f32>>> {
        // For batch operations, check circuit once and apply consistently
        if !self.should_allow_request() {
            self.total_rejections
                .fetch_add(texts.len() as u64, Ordering::Relaxed);
            return Ok(texts.iter().map(|t| self.generate_fallback(t)).collect());
        }

        self.total_calls
            .fetch_add(texts.len() as u64, Ordering::Relaxed);

        // Delegate to inner's batch method for ONNX batch inference
        match self.inner.encode_batch(texts) {
            Ok(embeddings) => {
                self.record_success();
                Ok(embeddings)
            }
            Err(_) => {
                // Batch failed — fall back to individual encoding with fallbacks
                self.record_failure();
                let mut results = Vec::with_capacity(texts.len());
                for text in texts {
                    match self.inner.encode(text) {
                        Ok(embedding) => results.push(embedding),
                        Err(_) => results.push(self.generate_fallback(text)),
                    }
                }
                Ok(results)
            }
        }
    }
}

/// Metrics snapshot for monitoring
#[derive(Debug, Clone)]
pub struct CircuitBreakerMetrics {
    pub state: CircuitState,
    pub consecutive_failures: u32,
    pub consecutive_successes: u32,
    pub total_calls: u64,
    pub total_rejections: u64,
    pub total_fallbacks: u64,
    pub time_in_current_state: Duration,
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn create_test_embedder() -> Arc<MiniLMEmbedder> {
        let config = super::super::minilm::EmbeddingConfig {
            model_path: PathBuf::from("dummy.onnx"),
            tokenizer_path: <REDACTED>"dummy.json"),
            max_length: 256,
            use_quantized: true,
            embed_timeout_ms: 5000,
        };
        Arc::new(MiniLMEmbedder::new_simplified(config).unwrap())
    }

    #[test]
    fn test_circuit_breaker_starts_closed() {
        let embedder = create_test_embedder();
        let resilient = ResilientEmbedder::with_defaults(embedder);
        assert_eq!(resilient.state(), CircuitState::Closed);
    }

    #[test]
    fn test_circuit_breaker_metrics() {
        let embedder = create_test_embedder();
        let resilient = ResilientEmbedder::with_defaults(embedder);

        let _ = resilient.encode("test");
        let metrics = resilient.metrics();

        assert!(metrics.total_calls >= 1);
        assert_eq!(metrics.state, CircuitState::Closed);
    }

    #[test]
    fn test_fallback_generates_valid_embedding() {
        let embedder = create_test_embedder();
        let resilient = ResilientEmbedder::with_defaults(embedder);

        let fallback = resilient.generate_fallback("test input");
        assert_eq!(fallback.len(), 384);

        // Check normalization
        let norm: f32 = fallback.iter().map(|x| x * x).sum::<f32>().sqrt();
        assert!((norm - 1.0).abs() < 1e-5 || norm == 0.0);
    }
}

import { useEffect, useRef, useState } from "react";
import { ExternalLink } from "lucide-react";
import { sendOAuthInput, startOAuthLogin } from "@/lib/seat/client";
import type { OAuthFlowEvent, ProviderInfo } from "@/lib/seat/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

/**
 * A subscription/OAuth login, driven entirely by the seat's bridge stream.
 * Everything rendered here is an interaction pi's own flow asked for —
 * auth URLs, device codes, progress lines, a code to paste back. The token
 * exchange happens in the seat process; this component never sees or stores
 * a credential.
 */

type Notice = Extract<OAuthFlowEvent, { kind: "notify" }>["event"];
type Prompt = Extract<OAuthFlowEvent, { kind: "prompt" }>;

export function OAuthFlow({
  provider,
  onDone,
}: {
  provider: ProviderInfo;
  /** Called with the post-login provider status, or null on cancel/failure. */
  onDone: (updated: ProviderInfo | null) => void;
}) {
  const [notices, setNotices] = useState<Notice[]>([]);
  const [prompt, setPrompt] = useState<Prompt | null>(null);
  const [draft, setDraft] = useState("");
  const [error, setError] = useState<string | null>(null);
  const doneRef = useRef(false);

  useEffect(() => {
    const controller = new AbortController();
    // Deferred one tick: React StrictMode mounts, unmounts and remounts every
    // effect in development. Starting the flow synchronously fired TWO logins
    // back to back — the second 409'd against the first, and the first's
    // just-opened callback listener made the retry EADDRINUSE. The fake mount's
    // cleanup runs before the timer fires, so only the real mount ever starts.
    const timer = window.setTimeout(() => {
      void startOAuthLogin(
      provider.id,
      (event) => {
        switch (event.kind) {
          case "notify":
            setNotices((current) => [...current, event.event]);
            // A fresh auth URL is the flow asking for a browser; open one.
            if (event.event.type === "auth_url") window.open(event.event.url, "_blank", "noopener");
            break;
          case "prompt":
            setPrompt(event);
            setDraft("");
            break;
          case "prompt_cancelled":
            setPrompt((current) => (current?.prompt_id === event.prompt_id ? null : current));
            break;
          case "complete":
            doneRef.current = true;
            onDone(event.provider);
            break;
          case "error":
            setError(event.message);
            break;
        }
      },
      controller.signal,
      ).catch((cause) => {
        if (!(cause instanceof DOMException && cause.name === "AbortError")) {
          setError(cause instanceof Error ? cause.message : String(cause));
        }
      });
    }, 0);
    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
    // One flow per mount; provider identity is fixed for the mount's lifetime.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [provider.id]);

  const answer = (value: string) => {
    if (!prompt || !value.trim()) return;
    void sendOAuthInput(provider.id, prompt.prompt_id, value.trim()).then(() => setPrompt(null));
  };

  return (
    <div className="border-border bg-card mt-2 ml-4 rounded-lg border px-3 py-2.5">
      <div className="flex flex-col gap-1.5">
        {notices.map((notice, index) => {
          switch (notice.type) {
            case "auth_url":
              return (
                <p key={index} className="text-[12px] leading-relaxed">
                  {notice.instructions ?? "Finish signing in in your browser:"}{" "}
                  <a
                    href={notice.url}
                    target="_blank"
                    rel="noreferrer noopener"
                    className="text-foreground inline-flex items-center gap-1 underline underline-offset-2"
                  >
                    open login page
                    <ExternalLink aria-hidden="true" className="size-3" />
                  </a>
                </p>
              );
            case "device_code":
              return (
                <div key={index} className="text-[12px] leading-relaxed">
                  Enter this code at{" "}
                  <a
                    href={notice.verificationUri}
                    target="_blank"
                    rel="noreferrer noopener"
                    className="text-foreground underline underline-offset-2"
                  >
                    {notice.verificationUri}
                  </a>
                  <p className="mono mt-1 text-[15px] font-semibold tracking-widest">
                    {notice.userCode}
                  </p>
                </div>
              );
            case "info":
              return (
                <p key={index} className="text-muted-foreground text-[12px] leading-relaxed">
                  {notice.message}
                  {notice.links?.map((link) => (
                    <a
                      key={link.url}
                      href={link.url}
                      target="_blank"
                      rel="noreferrer noopener"
                      className="text-foreground ml-1 underline underline-offset-2"
                    >
                      {link.label ?? link.url}
                    </a>
                  ))}
                </p>
              );
            case "progress":
              return (
                <p key={index} className="text-muted-foreground text-[11px]">
                  {notice.message}
                </p>
              );
            default:
              return null;
          }
        })}
        {notices.length === 0 && !error ? (
          <p className="text-muted-foreground text-[12px]">Starting {provider.name} sign-in…</p>
        ) : null}
      </div>

      {prompt ? (
        prompt.type === "select" ? (
          <div className="mt-2 flex flex-col gap-1">
            <p className="text-[12px]">{prompt.message}</p>
            {(prompt.options ?? []).map((option) => (
              <Button
                key={option.id}
                size="sm"
                variant="outline"
                className="justify-start"
                onClick={() => answer(option.id)}
              >
                {option.label}
              </Button>
            ))}
          </div>
        ) : (
          <form
            className="mt-2 flex items-center gap-2"
            onSubmit={(e) => {
              e.preventDefault();
              answer(draft);
            }}
          >
            <Input
              autoFocus
              type={prompt.type === "secret" ? "password" : "text"}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              placeholder={prompt.placeholder ?? prompt.message}
              aria-label={prompt.message}
              autoComplete="off"
              className="max-w-[360px]"
            />
            <Button type="submit" size="sm" disabled={!draft.trim()}>
              Submit
            </Button>
          </form>
        )
      ) : null}

      {error ? <p className="text-destructive mt-2 text-[11px] leading-relaxed">{error}</p> : null}

      <div className="mt-2">
        <Button size="sm" variant="ghost" onClick={() => onDone(null)}>
          {error ? "Close" : "Cancel"}
        </Button>
      </div>
    </div>
  );
}

#!/usr/bin/env node
/**
 * A deterministic OpenAI-compatible model endpoint, for exercising the seat
 * harness end-to-end without a real model.
 *
 * Why this exists: the harness's plumbing — streaming, tool calls, the memory
 * tools, both learning loops, the ledger, persistence — is exactly the part
 * that must be verified before a demo, and none of it depends on model
 * intelligence. The seat's local providers (Ollama / LM Studio / vLLM) all
 * speak this API against a configurable baseUrl, so pointing
 * LMSTUDIO_BASE_URL at this process runs the REAL harness code path with a
 * model whose behaviour is scripted and assertable.
 *
 * Behaviour per /chat/completions call, decided by the conversation tail:
 *   - If the last message is a tool result: stream a text answer that cites
 *     the first `[mem:xxxxxxxx]` short-id present in that result (the seat's
 *     citation contract), or says plainly that nothing surfaced.
 *   - Otherwise: emit a `recall_memory` tool call whose query is the last
 *     user message. This drives the seat's full tool round-trip.
 *
 * Every response carries usage numbers so the usage/billing pipeline runs.
 * Nothing here is random; same input, same output, always.
 */
import { createServer } from "node:http";

const PORT = Number(process.env.FIXTURE_PORT ?? 3210);
const MODEL_ID = "fixture-deterministic-v1";

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

/** SSE chunk in OpenAI streaming format. */
function chunk(res, delta, finishReason = null) {
  const payload = {
    id: "chatcmpl-fixture",
    object: "chat.completion.chunk",
    created: 0,
    model: MODEL_ID,
    choices: [{ index: 0, delta, finish_reason: finishReason }],
  };
  res.write(`data: ${JSON.stringify(payload)}\n\n`);
}

function usageChunk(res, promptTokens, completionTokens) {
  res.write(
    `data: ${JSON.stringify({
      id: "chatcmpl-fixture",
      object: "chat.completion.chunk",
      created: 0,
      model: MODEL_ID,
      choices: [],
      usage: {
        prompt_tokens: <REDACTED>
        completion_tokens: <REDACTED>
        total_tokens: <REDACTED> + completionTokens,
      },
    })}\n\n`,
  );
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://127.0.0.1:${PORT}`);

  if (req.method === "GET" && url.pathname.endsWith("/models")) {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ object: "list", data: [{ id: MODEL_ID, object: "model" }] }));
    return;
  }

  if (req.method === "POST" && url.pathname.endsWith("/chat/completions")) {
    const body = JSON.parse((await readBody(req)) || "{}");
    const messages = Array.isArray(body.messages) ? body.messages : [];
    const last = messages[messages.length - 1] ?? {};
    const promptTokens = <REDACTED> Math.round(JSON.stringify(messages).length / 4));

    res.writeHead(200, {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    });

    const isToolResult = last.role === "tool";
    if (isToolResult) {
      const content =
        typeof last.content === "string" ? last.content : JSON.stringify(last.content ?? "");
      const cite = /\[mem:[0-9a-f]{8}\]/.exec(content)?.[0];
      const text = cite
        ? `Based on recalled memory ${cite}, the retrieved evidence answers the question directly.`
        : "Recall returned nothing for that cue; no memory supports an answer.";
      chunk(res, { role: "assistant" });
      for (const word of text.split(/(?<= )/)) chunk(res, { content: word });
      chunk(res, {}, "stop");
      usageChunk(res, promptTokens, Math.round(text.length / 4));
    } else {
      const lastUser = [...messages].reverse().find((m) => m.role === "user");
      const query = String(
        typeof lastUser?.content === "string" ? lastUser.content : "context",
      ).slice(0, 120);
      chunk(res, { role: "assistant" });
      chunk(res, {
        tool_calls: [
          {
            index: 0,
            id: "call_fixture_1",
            type: "function",
            function: { name: "recall_memory", arguments: JSON.stringify({ query }) },
          },
        ],
      });
      chunk(res, {}, "tool_calls");
      usageChunk(res, promptTokens, 12);
    }
    res.write("data: [DONE]\n\n");
    res.end();
    return;
  }

  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: { message: `no route: ${req.method} ${url.pathname}` } }));
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`fixture model listening on http://127.0.0.1:${PORT}/v1 (model: ${MODEL_ID})`);
});

